const submitSubmission = `-- name: SubmitSubmission :one
UPDATE submissions
SET status = $1, version = version + 1,
    first_submitted_at = COALESCE(first_submitted_at, $2::timestamptz), submitted_at = $2::timestamptz,
    late = (deadline_at IS NOT NULL AND COALESCE(first_submitted_at, $2::timestamptz) > deadline_at),
    checked_at = CASE WHEN $3::boolean THEN COALESCE(checked_at, $2::timestamptz) ELSE checked_at END,
    auto_points = $4::integer, final_points = $5::integer, updated_at = $2::timestamptz
WHERE id = $6
RETURNING late, first_submitted_at IS DISTINCT FROM submitted_at AS resubmission
`

type SubmitSubmissionParams struct {
	Status      domain.SubmissionStatus
	Now         time.Time
	Checked     bool
	AutoPoints  int32
	FinalPoints int32
	ID          domain.SubmissionID
}

type SubmitSubmissionRow struct {
	Late         bool
	Resubmission bool
}

func (q *Queries) SubmitSubmission(ctx context.Context, arg SubmitSubmissionParams) (SubmitSubmissionRow, error) {
	row := q.db.QueryRow(ctx, submitSubmission,
		arg.Status,
		arg.Now,
		arg.Checked,
		arg.AutoPoints,
		arg.FinalPoints,
		arg.ID,
	)
	var i SubmitSubmissionRow
	err := row.Scan(&i.Late, &i.Resubmission)
	return i, err
}

const upsertAnswer = `-- name: UpsertAnswer :execrows
INSERT INTO answers (submission_id, question_id, value, created_at, updated_at)
VALUES ($1, $2, $3, $4, $4)
ON CONFLICT (submission_id, question_id) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at
WHERE answers.frozen_at IS NULL
`

type UpsertAnswerParams struct {
	SubmissionID domain.SubmissionID
	QuestionID   domain.QuestionID
	Value        []byte
	Now          time.Time
}

func (q *Queries) UpsertAnswer(ctx context.Context, arg UpsertAnswerParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertAnswer,
		arg.SubmissionID,
		arg.QuestionID,
		arg.Value,
		arg.Now,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

